static void test_frombytes_tobytes(void) {
    TEST_SUITE("p256_fe_frombytes / p256_fe_tobytes — roundtrip against P");

    for (int i = 0; i < NVALS; i++) {
        uint64_t fe[4];
        uint8_t out[32];
        p256_fe_frombytes(fe, VALS[i]);
        p256_fe_tobytes(out, fe);
        ASSERT_EQ("roundtrip matches input", 0, memcmp(out, VALS[i], 32));
    }

    // Known-value spot check: 1 -> limb0 = 1, limbs 1-3 = 0.
    uint64_t one[4];
    p256_fe_frombytes(one, VALS[1]);
    ASSERT_EQ("fe(1) limb0", 1, (int64_t)one[0]);
    ASSERT_EQ("fe(1) limb1", 0, (int64_t)one[1]);
    ASSERT_EQ("fe(1) limb2", 0, (int64_t)one[2]);
    ASSERT_EQ("fe(1) limb3", 0, (int64_t)one[3]);
}

static void test_add(void) {
    TEST_SUITE("p256_fe_add — a + b mod p");

    for (int i = 0; i < NPAIRS; i++) {
        uint64_t a[4], b[4], out[4];
        uint8_t outb[32];
        p256_fe_frombytes(a, PAIRS[i].a);
        p256_fe_frombytes(b, PAIRS[i].b);
        p256_fe_add(out, a, b);
        p256_fe_tobytes(outb, out);
        ASSERT_EQ("a+b mod p", 0, memcmp(outb, PAIRS[i].sum, 32));
    }

    // out may alias a and/or b.
    uint64_t a[4], b[4];
    p256_fe_frombytes(a, PAIRS[0].a);
    p256_fe_frombytes(b, PAIRS[0].b);
    p256_fe_add(a, a, b);
    uint8_t outb[32];
    p256_fe_tobytes(outb, a);
    ASSERT_EQ("a+b mod p, out aliases a", 0, memcmp(outb, PAIRS[0].sum, 32));
}

static void test_sub(void) {
    TEST_SUITE("p256_fe_sub — a - b mod p");

    for (int i = 0; i < NPAIRS; i++) {
        uint64_t a[4], b[4], out[4];
        uint8_t outb[32];
        p256_fe_frombytes(a, PAIRS[i].a);
        p256_fe_frombytes(b, PAIRS[i].b);
        p256_fe_sub(out, a, b);
        p256_fe_tobytes(outb, out);
        ASSERT_EQ("a-b mod p", 0, memcmp(outb, PAIRS[i].diff, 32));
    }

    uint64_t a[4], b[4];
    p256_fe_frombytes(a, PAIRS[0].a);
    p256_fe_frombytes(b, PAIRS[0].b);
    p256_fe_sub(b, a, b);
    uint8_t outb[32];
    p256_fe_tobytes(outb, b);
    ASSERT_EQ("a-b mod p, out aliases b", 0, memcmp(outb, PAIRS[0].diff, 32));
}

static void test_mul(void) {
    TEST_SUITE("p256_fe_mul — a * b mod p");

    for (int i = 0; i < NPAIRS; i++) {
        uint64_t a[4], b[4], out[4];
        uint8_t outb[32];
        p256_fe_frombytes(a, PAIRS[i].a);
        p256_fe_frombytes(b, PAIRS[i].b);
        p256_fe_mul(out, a, b);
        p256_fe_tobytes(outb, out);
        ASSERT_EQ("a*b mod p", 0, memcmp(outb, PAIRS[i].prod, 32));
    }

    uint64_t a[4], b[4];
    p256_fe_frombytes(a, PAIRS[0].a);
    p256_fe_frombytes(b, PAIRS[0].b);
    p256_fe_mul(a, a, b);
    uint8_t outb[32];
    p256_fe_tobytes(outb, a);
    ASSERT_EQ("a*b mod p, out aliases a", 0, memcmp(outb, PAIRS[0].prod, 32));
}

static void test_sqr(void) {
    TEST_SUITE("p256_fe_sqr — a^2 mod p");

    for (int i = 0; i < NSQR; i++) {
        uint64_t a[4], out[4];
        uint8_t outb[32];
        p256_fe_frombytes(a, SQRS[i].a);
        p256_fe_sqr(out, a);
        p256_fe_tobytes(outb, out);
        ASSERT_EQ("a^2 mod p", 0, memcmp(outb, SQRS[i].sq, 32));
    }

    // p256_fe_sqr(a) == p256_fe_mul(a, a) for every squaring vector.
    for (int i = 0; i < NSQR; i++) {
        uint64_t a[4], sq[4], mul[4];
        uint8_t sqb[32], mulb[32];
        p256_fe_frombytes(a, SQRS[i].a);
        p256_fe_sqr(sq, a);
        p256_fe_mul(mul, a, a);
        p256_fe_tobytes(sqb, sq);
        p256_fe_tobytes(mulb, mul);
        ASSERT_EQ("sqr(a) == mul(a,a)", 0, memcmp(sqb, mulb, 32));
    }
}

static void test_reduced_range(void) {
    TEST_SUITE("results are always canonical (< p)");

    for (int i = 0; i < NPAIRS; i++) {
        uint64_t a[4], b[4], sum[4], diff[4], prod[4];
        uint8_t sumb[32], diffb[32], prodb[32], pfe[4 * 8];
        (void)pfe;
        p256_fe_frombytes(a, PAIRS[i].a);
        p256_fe_frombytes(b, PAIRS[i].b);
        p256_fe_add(sum, a, b);
        p256_fe_sub(diff, a, b);
        p256_fe_mul(prod, a, b);
        p256_fe_tobytes(sumb, sum);
        p256_fe_tobytes(diffb, diff);
        p256_fe_tobytes(prodb, prod);
        ASSERT_EQ("sum < P", 1, memcmp(sumb, P, 32) < 0);
        ASSERT_EQ("diff < P", 1, memcmp(diffb, P, 32) < 0);
        ASSERT_EQ("prod < P", 1, memcmp(prodb, P, 32) < 0);
    }
}

static void test_inv(void) {
    TEST_SUITE("p256_fe_inv — a^-1 mod p");

    for (int i = 0; i < NINV; i++) {
        uint64_t a[4], out[4];
        uint8_t outb[32];
        p256_fe_frombytes(a, INVS[i].a);
        p256_fe_inv(out, a);
        p256_fe_tobytes(outb, out);
        ASSERT_EQ("a^-1 mod p", 0, memcmp(outb, INVS[i].inv, 32));
    }

    // a * a^-1 == 1 for every non-zero vector.
    for (int i = 1; i < NINV; i++) {
        uint64_t a[4], ainv[4], one[4];
        uint8_t oneb[32];
        p256_fe_frombytes(a, INVS[i].a);
        p256_fe_inv(ainv, a);
        p256_fe_mul(one, a, ainv);
        p256_fe_tobytes(oneb, one);
        ASSERT_EQ("a * a^-1 == 1", 1, oneb[31] == 1);
        int rest_zero = 1;
        for (int j = 0; j < 31; j++) {
            if (oneb[j] != 0) rest_zero = 0;
        }
        ASSERT_EQ("a * a^-1 high bytes are zero", 1, rest_zero);
    }
}

int main(void) {
    test_frombytes_tobytes();
    test_add();
    test_sub();
    test_mul();
    test_sqr();
    test_inv();
    test_reduced_range();
    test_summary();
    return 0;
}

